import Foundation

/// An oracle for SPEC 4.1's rounding: 4,082 (value, places, expected) triples
/// as IEEE 754 bit patterns, generated with Python's `Fraction`, which computes
/// the exact decimal expansion with no floating point anywhere in the answer.
///
/// A table rather than a second implementation, because a second implementation
/// written by the same hand shares the same misreading. The rows are chosen to
/// sit where scale-multiply-and-divide and exact rounding diverge: on and just
/// off the half-way grid at one and six places, plus plausible coordinates,
/// elevations, subnormals and random bit patterns.
///
/// The rows are also chosen so that every arm of the 128-bit shift inside
/// `Rounding` is taken, and `RoundingTests.testTheOracleReachesEveryShiftArm`
/// asserts that rather than assuming it. The first version of this table did
/// not: red-proofing found that deleting the `shift == 64` arm entirely, and
/// mis-setting the subnormal exponent, both left the suite green.
///
/// The Kotlin seat has generated a larger language-neutral table from Go for
/// `corpus/numbers/`. When that lands this file should give way to it — it will
/// be the same instrument, shared, which is strictly better. It had not landed
/// when this was written; `RoundingTests.testTheSharedNumberTableIsStillAbsent`
/// is what will notice.
